#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=14
REPOSITORY_ROOT=$(cd "$(dirname "$0")/.." && pwd)

banner "Voice Agent host setup"

stage "Verify the Human Merge"
say "The release must come from the exact commit accepted on origin/main."
git -C "$REPOSITORY_ROOT" fetch origin main
MERGED_COMMIT=$(git -C "$REPOSITORY_ROOT" rev-parse refs/remotes/origin/main)
CHECKOUT_COMMIT=$(git -C "$REPOSITORY_ROOT" rev-parse HEAD)
if [[ $CHECKOUT_COMMIT != "$MERGED_COMMIT" ]] || \
  [[ -n $(git -C "$REPOSITORY_ROOT" status --porcelain) ]]; then
  warn "Use a clean checkout of origin/main so the provisioning code has passed the Human Merge boundary."
  exit 1
fi
if ! "$REPOSITORY_ROOT/ops/release/verify-human-merge.sh" \
  JacobStephens2/voice-agent "$MERGED_COMMIT"; then
  warn "GitHub does not identify this exact commit as a Human Merge to main."
  exit 1
fi
note "Merged commit: $MERGED_COMMIT"
confirm "Install this exact merged commit?" || exit 1

stage "Provision least-privilege GitHub source access"
say "Create a GitHub App with read-only Contents permission, no write permissions, and install it only on JacobStephens2/voice-agent."
step "Download one private-key PEM for the App onto this host; do not paste it into this wizard or a shell command."
ask GITHUB_APP_ID "GitHub App ID"
ask GITHUB_APP_INSTALLATION_ID "GitHub App installation ID"
ask GITHUB_APP_KEY_PATH "Absolute path to the downloaded GitHub App PEM"
if [[ ! $GITHUB_APP_ID =~ ^[0-9]+$ || \
  ! $GITHUB_APP_INSTALLATION_ID =~ ^[0-9]+$ || \
  $GITHUB_APP_KEY_PATH != /* || ! -f $GITHUB_APP_KEY_PATH ]]; then
  warn "Provide numeric App/installation IDs and an existing absolute PEM path."
  exit 1
fi
GITHUB_APP_KEY_PATH=$(realpath "$GITHUB_APP_KEY_PATH")
case "$GITHUB_APP_KEY_PATH" in
  "$REPOSITORY_ROOT"|"$REPOSITORY_ROOT"/*)
    warn "Provider credentials cannot be read from inside the repository."
    exit 1
    ;;
esac
sudo install -d -o root -g root -m 0755 /etc/voice-agent
github_app_config=$(mktemp)
printf '%s\t%s\n' "$GITHUB_APP_ID" "$GITHUB_APP_INSTALLATION_ID" \
  > "$github_app_config"
if sudo test -e /etc/voice-agent/github-app.conf && \
  ! sudo cmp -s "$github_app_config" /etc/voice-agent/github-app.conf; then
  rm -f -- "$github_app_config"
  warn "Pinned GitHub App identity differs; this wizard will not replace it."
  exit 1
fi
if sudo test -e /etc/voice-agent/github-app-private-key.pem && \
  ! sudo cmp -s "$GITHUB_APP_KEY_PATH" \
    /etc/voice-agent/github-app-private-key.pem; then
  rm -f -- "$github_app_config"
  warn "Pinned GitHub App key differs; rotate it through a separately reviewed procedure."
  exit 1
fi
if ! sudo test -e /etc/voice-agent/github-app.conf; then
  sudo install -o root -g root -m 0600 "$github_app_config" \
    /etc/voice-agent/github-app.conf
fi
if ! sudo test -e /etc/voice-agent/github-app-private-key.pem; then
  sudo install -o root -g root -m 0600 "$GITHUB_APP_KEY_PATH" \
    /etc/voice-agent/github-app-private-key.pem
fi
rm -f -- "$github_app_config"
unset GITHUB_APP_ID GITHUB_APP_INSTALLATION_ID GITHUB_APP_KEY_PATH
note "The PEM is root-only. Keep or securely remove the downloaded original according to your key-custody policy."

stage "Connect Telnyx SIP to LiveKit Cloud"
say "The host receives only LiveKit credentials. Telnyx SIP credentials stay inside the Telnyx and LiveKit provider configurations."
open_url "https://cloud.livekit.io"
step "Open the personal LiveKit project → Settings. Copy its WebSocket URL, API key, and API secret."
ask LIVEKIT_URL "LiveKit WebSocket URL (wss://...):"
ask_secret LIVEKIT_API_KEY "LiveKit API key:"
ask_secret LIVEKIT_API_SECRET "LiveKit API secret:"
open_url "https://developers.telnyx.com/docs/voice/sip-trunking/livekit-configuration-guide"
step "In Telnyx Mission Control, create an FQDN SIP connection pointed at the LiveKit project SIP URI, attach an outbound voice profile, and assign the dedicated number."
step "Enable credential authentication for outbound calls. Keep that username/password in the provider dashboards; do not place them on the Agent Host."
step "In LiveKit, create an inbound trunk for the dedicated number restricted to Telnyx SIP addresses, then a dispatch rule for agent voice-agent-telephone."
step "Create a stored outbound trunk using sip.telnyx.com and the Telnyx credential."
step 'In the LiveKit outbound trunk JSON editor, set "headers": {"X-Telnyx-Username": "<same Telnyx username>"}. Use the credential username as the value; headers_to_attributes maps response headers and does not send the initial INVITE header.'
ask TELNYX_NUMBER "Dedicated Telnyx number in E.164 form (+...):"
ask LIVEKIT_INBOUND_TRUNK_ID "LiveKit inbound trunk ID (ST_...):"
ask LIVEKIT_OUTBOUND_TRUNK_ID "LiveKit outbound trunk ID (ST_...):"
if [[ ! $LIVEKIT_URL =~ ^wss://[A-Za-z0-9.-]+(:[0-9]+)?/?$ || \
  ! $LIVEKIT_API_KEY =~ ^[A-Za-z0-9_-]+$ || \
  ! $LIVEKIT_API_SECRET =~ ^[A-Za-z0-9_-]+$ || \
  ! $TELNYX_NUMBER =~ ^\+[1-9][0-9]{7,14}$ || \
  ! $LIVEKIT_INBOUND_TRUNK_ID =~ ^ST_[A-Za-z0-9_-]+$ || \
  ! $LIVEKIT_OUTBOUND_TRUNK_ID =~ ^ST_[A-Za-z0-9_-]+$ ]]; then
  warn "Provide the exact LiveKit URL/credentials, E.164 Telnyx number, and ST_ trunk IDs."
  exit 1
fi
livekit_environment=$(mktemp)
printf 'LIVEKIT_URL=%s\nLIVEKIT_API_KEY=%s\nLIVEKIT_API_SECRET=%s\n' \
  "$LIVEKIT_URL" "$LIVEKIT_API_KEY" "$LIVEKIT_API_SECRET" \
  > "$livekit_environment"
if sudo test -e /etc/voice-agent/livekit.env && \
  ! sudo cmp -s "$livekit_environment" /etc/voice-agent/livekit.env; then
  confirm "Replace the existing root-owned LiveKit credential source?" || {
    rm -f -- "$livekit_environment"
    exit 1
  }
fi
sudo install -o root -g root -m 0600 "$livekit_environment" \
  /etc/voice-agent/livekit.env
rm -f -- "$livekit_environment"
unset LIVEKIT_API_KEY LIVEKIT_API_SECRET
note "LiveKit credentials are root-owned and injected only into the telephone worker."

stage "Configure Resend Silent Notifications"
say "Resend sends only generic completion notices from a dedicated verified subdomain. Open and click tracking must remain disabled."
open_url "https://resend.com/domains"
step "Add notify.stephens.page as a sending domain, add the displayed DNS records, and wait until Resend reports the domain as verified."
step "Open the domain tracking configuration and confirm both open tracking and click tracking are disabled."
step "Copy the verified domain ID from the domain page."
ask RESEND_DOMAIN_ID "Verified Resend domain ID:"
ask VOICE_AGENT_NOTIFICATION_SUBDOMAIN "Verified notification subdomain [notify.stephens.page]:"
if [[ -z $VOICE_AGENT_NOTIFICATION_SUBDOMAIN ]]; then
  VOICE_AGENT_NOTIFICATION_SUBDOMAIN=notify.stephens.page
fi
open_url "https://resend.com/api-keys"
step "Create a sending API key for the Voice Agent and copy it now; Resend will not show it again."
ask_secret RESEND_API_KEY "Resend sending API key:"
if [[ ! $RESEND_DOMAIN_ID =~ ^[A-Za-z0-9_-]+$ || \
  ! $VOICE_AGENT_NOTIFICATION_SUBDOMAIN =~ ^[a-z0-9.-]+$ || \
  ! $RESEND_API_KEY =~ ^re_[A-Za-z0-9_-]+$ ]]; then
  warn "Provide the exact Resend domain ID, verified subdomain, and re_ API key."
  exit 1
fi
resend_environment=$(mktemp)
printf 'RESEND_API_KEY=%s\nRESEND_DOMAIN_ID=%s\nVOICE_AGENT_NOTIFICATION_SUBDOMAIN=%s\n' \
  "$RESEND_API_KEY" "$RESEND_DOMAIN_ID" \
  "$VOICE_AGENT_NOTIFICATION_SUBDOMAIN" > "$resend_environment"
if sudo test -e /etc/voice-agent/resend.env && \
  ! sudo cmp -s "$resend_environment" /etc/voice-agent/resend.env; then
  confirm "Replace the existing root-owned Resend credential source?" || {
    rm -f -- "$resend_environment"
    exit 1
  }
fi
sudo install -o root -g root -m 0600 "$resend_environment" \
  /etc/voice-agent/resend.env
rm -f -- "$resend_environment"
unset RESEND_API_KEY
note "The Resend credential is root-owned and injected only into the background worker."

stage "Install and promote the immutable release"
say "This pins reviewed root orchestration, creates unprivileged identities, private state directories, and hardened services."
if [[ $REPOSITORY_ROOT == *$'\n'* || $REPOSITORY_ROOT == *'"'* ]]; then
  warn "The registered repository path cannot contain a newline or double quote."
  exit 1
fi
ROOT_ORCHESTRATOR=/usr/local/libexec/voice-agent
# shellcheck source=release/deployment-authority-manifest.sh
source "$REPOSITORY_ROOT/ops/release/deployment-authority-manifest.sh"
sudo install -d -o root -g root -m 0755 \
  "$ROOT_ORCHESTRATOR" "$ROOT_ORCHESTRATOR/systemd" \
  "$ROOT_ORCHESTRATOR/apparmor"
for script in "${voice_agent_authority_scripts[@]}"; do
  if sudo test -e "$ROOT_ORCHESTRATOR/$script" && \
    ! sudo cmp -s "$REPOSITORY_ROOT/ops/release/$script" \
      "$ROOT_ORCHESTRATOR/$script"; then
    warn "Pinned deployment authority differs at $script; this wizard will not overwrite it."
    exit 1
  fi
  if ! sudo test -e "$ROOT_ORCHESTRATOR/$script"; then
    sudo install -o root -g root -m 0755 \
      "$REPOSITORY_ROOT/ops/release/$script" "$ROOT_ORCHESTRATOR/$script"
  fi
done
for mapping in "${voice_agent_authority_apparmor_profiles[@]}"; do
  source_path=${mapping%%:*}
  target_path=${mapping#*:}
  if sudo test -e "$ROOT_ORCHESTRATOR/apparmor/$target_path" && \
    ! sudo cmp -s "$REPOSITORY_ROOT/$source_path" \
      "$ROOT_ORCHESTRATOR/apparmor/$target_path"; then
    warn "Pinned AppArmor authority differs at $target_path; this wizard will not overwrite it."
    exit 1
  fi
  if ! sudo test -e "$ROOT_ORCHESTRATOR/apparmor/$target_path"; then
    sudo install -o root -g root -m 0644 \
      "$REPOSITORY_ROOT/$source_path" \
      "$ROOT_ORCHESTRATOR/apparmor/$target_path"
  fi
done
for mapping in "${voice_agent_authority_programs[@]}"; do
  source_path=${mapping%%:*}
  target_path=${mapping#*:}
  if sudo test -e "$ROOT_ORCHESTRATOR/$target_path" && \
    ! sudo cmp -s "$REPOSITORY_ROOT/$source_path" \
      "$ROOT_ORCHESTRATOR/$target_path"; then
    warn "Pinned deployment authority differs at $target_path; this wizard will not overwrite it."
    exit 1
  fi
  if ! sudo test -e "$ROOT_ORCHESTRATOR/$target_path"; then
    sudo install -o root -g root -m 0644 \
      "$REPOSITORY_ROOT/$source_path" "$ROOT_ORCHESTRATOR/$target_path"
  fi
done
for mapping in "${voice_agent_authority_extras[@]}"; do
  source_path=${mapping%%:*}
  target_path=${mapping#*:}
  if sudo test -e "$ROOT_ORCHESTRATOR/$target_path" && \
    ! sudo cmp -s "$REPOSITORY_ROOT/$source_path" \
      "$ROOT_ORCHESTRATOR/$target_path"; then
    warn "Pinned deployment authority differs at $target_path; this wizard will not overwrite it."
    exit 1
  fi
  if ! sudo test -e "$ROOT_ORCHESTRATOR/$target_path"; then
    sudo install -o root -g root -m 0755 \
      "$REPOSITORY_ROOT/$source_path" "$ROOT_ORCHESTRATOR/$target_path"
  fi
done
sudo install -d -o root -g root -m 0755 /etc/apparmor.d
for mapping in "${voice_agent_authority_apparmor_profiles[@]}"; do
  profile=${mapping#*:}
  if sudo test -e "/etc/apparmor.d/$profile" && \
    ! sudo cmp -s "$ROOT_ORCHESTRATOR/apparmor/$profile" \
      "/etc/apparmor.d/$profile"; then
    warn "Active AppArmor profile differs at $profile; this wizard will not overwrite it."
    exit 1
  fi
  sudo /usr/sbin/apparmor_parser -Q \
    "$ROOT_ORCHESTRATOR/apparmor/$profile"
  sudo install -o root -g root -m 0644 \
    "$ROOT_ORCHESTRATOR/apparmor/$profile" "/etc/apparmor.d/$profile"
  sudo /usr/sbin/apparmor_parser -r "/etc/apparmor.d/$profile"
done
for unit in "${voice_agent_authority_units[@]}"; do
  if sudo test -e "$ROOT_ORCHESTRATOR/systemd/$unit" && \
    ! sudo cmp -s "$REPOSITORY_ROOT/ops/systemd/$unit" \
      "$ROOT_ORCHESTRATOR/systemd/$unit"; then
    warn "Pinned service authority differs at $unit; this wizard will not overwrite it."
    exit 1
  fi
  if ! sudo test -e "$ROOT_ORCHESTRATOR/systemd/$unit"; then
    sudo install -o root -g root -m 0644 \
      "$REPOSITORY_ROOT/ops/systemd/$unit" "$ROOT_ORCHESTRATOR/systemd/$unit"
  fi
done
sudo install -d -o root -g root -m 0755 /etc/voice-agent
repository_config=$(mktemp)
printf '%s\n' "$REPOSITORY_ROOT" > "$repository_config"
if sudo test -e /etc/voice-agent/promotion-repository && \
  ! sudo cmp -s "$repository_config" /etc/voice-agent/promotion-repository; then
  rm -f -- "$repository_config"
  warn "Registered repository differs; this wizard will not expand deployment scope."
  exit 1
fi
if ! sudo test -e /etc/voice-agent/promotion-repository; then
  sudo install -o root -g root -m 0644 "$repository_config" \
    /etc/voice-agent/promotion-repository
fi
rm -f -- "$repository_config"
SOURCE_MIRROR=/var/lib/voice-agent-source/repository.git
sudo install -d -o root -g root -m 0755 /var/lib/voice-agent-source
if ! sudo test -d "$SOURCE_MIRROR"; then
  sudo git init --bare "$SOURCE_MIRROR"
fi
if [[ $(sudo stat -c %U "$SOURCE_MIRROR") != root ]]; then
  warn "Voice Agent source mirror is not root-owned."
  exit 1
fi
sudo chmod -R go-w "$SOURCE_MIRROR"
sudo install -o root -g root -m 0644 \
  "$ROOT_ORCHESTRATOR/systemd/voice-agent-promotion-resume.path" \
  /etc/systemd/system/voice-agent-promotion-resume.path
sudo install -o root -g root -m 0644 \
  "$ROOT_ORCHESTRATOR/systemd/voice-agent-promotion-resume.service" \
  /etc/systemd/system/voice-agent-promotion-resume.service
sudo systemctl daemon-reload
if ! sudo "$ROOT_ORCHESTRATOR/install-release.sh" \
  "$REPOSITORY_ROOT" "$MERGED_COMMIT"; then
  sudo "$ROOT_ORCHESTRATOR/record-promotion-failure.sh" \
    "$MERGED_COMMIT" release-build || true
  exit 1
fi
sudo systemctl enable --now voice-agent-promotion-resume.path
sudo "$ROOT_ORCHESTRATOR/promote-release.sh" "$MERGED_COMMIT"
sudo "$ROOT_ORCHESTRATOR/install-prometheus-scrape.sh"
sudo "$ROOT_ORCHESTRATOR/install-grafana-dashboard.sh" "$REPOSITORY_ROOT"
sudo systemd-analyze security \
  voice-agent-api.service voice-agent-worker.service \
  voice-agent-keeplore-publisher.service \
  voice-agent-repository-administration.service voice-agent-subagent.service \
  voice-agent-broker.service \
  voice-agent-probes.service \
  voice-agent-promotion-resume.service \
  --no-pager || true
pause "Review the hardening report, then press Enter."

stage "Enable ordered Human Merge Promotion"
say "Each authenticated human PR merge to main will ask the Agent Host to process every verified, unseen Human Merge transition in GitHub order."
step "Use a restricted SSH identity whose remote account may run only the root-owned promote-main.sh queue through passwordless sudo."
step "Base64-encode its private key and the verified known_hosts entry as single lines before entering them here."
ask DEPLOY_USER "Restricted Agent Host SSH user"
ask REPOSITORY_PATH "Absolute Voice Agent repository path on the Agent Host"
ask_secret DEPLOY_KEY_B64 "Base64-encoded restricted SSH private key"
ask_secret KNOWN_HOSTS_B64 "Base64-encoded verified known_hosts entry"
set_var VOICE_AGENT_DEPLOY_HOST "stephens.page"
set_var VOICE_AGENT_DEPLOY_USER "$DEPLOY_USER"
set_var VOICE_AGENT_REPOSITORY_PATH "$REPOSITORY_PATH"
set_secret VOICE_AGENT_DEPLOY_KEY_B64 "$DEPLOY_KEY_B64"
set_secret VOICE_AGENT_KNOWN_HOSTS_B64 "$KNOWN_HOSTS_B64"
unset DEPLOY_KEY_B64 KNOWN_HOSTS_B64
pause "Confirm the repository variables and restricted deploy secrets are present on GitHub."

stage "Enable the authenticated TLS origin"
say "Apache will serve only the static PWA and proxy /api/ to the localhost API."
sudo install -o root -g root -m 0644 \
  "/opt/voice-agent/releases/$MERGED_COMMIT/ops/apache/voice.stephens.page-acme.conf" \
  /etc/apache2/sites-available/voice.stephens.page-acme.conf
sudo a2enmod ssl proxy proxy_http headers rewrite
sudo a2ensite voice.stephens.page-acme.conf
sudo apache2ctl configtest
sudo systemctl reload apache2
if [[ ! -f /etc/letsencrypt/live/voice.stephens.page/fullchain.pem ]]; then
  step "Certbot will ask for the certificate contact/TOS choices and obtain the voice.stephens.page certificate."
  sudo certbot certonly --apache -d voice.stephens.page
fi
sudo install -o root -g root -m 0644 \
  "/opt/voice-agent/releases/$MERGED_COMMIT/ops/apache/voice.stephens.page.conf" \
  /etc/apache2/sites-available/voice.stephens.page.conf
sudo a2dissite voice.stephens.page-acme.conf
sudo a2ensite voice.stephens.page.conf
sudo apache2ctl configtest
sudo systemctl reload apache2
open_url "https://voice.stephens.page"
pause "Confirm that the Voice Agent authentication screen loads over HTTPS."

stage "Bootstrap two passkeys and Recovery Codes"
say "Each Bootstrap Code is short-lived and single-use. It is printed here and never stored."
FIRST_BOOTSTRAP_CODE=$(sudo -u voice-agent env \
  VOICE_AGENT_DATABASE_PATH=/var/lib/voice-agent/voice-agent.sqlite \
  /usr/bin/node --experimental-strip-types \
  /opt/voice-agent/current/apps/api/src/bootstrap-cli.ts)
printf '  First Bootstrap Code: %s\n' "$FIRST_BOOTSTRAP_CODE"
open_url "https://voice.stephens.page"
step "Enroll the first passkey with that code."
pause "Press Enter after the first passkey succeeds."
SECOND_BOOTSTRAP_CODE=$(sudo -u voice-agent env \
  VOICE_AGENT_DATABASE_PATH=/var/lib/voice-agent/voice-agent.sqlite \
  /usr/bin/node --experimental-strip-types \
  /opt/voice-agent/current/apps/api/src/bootstrap-cli.ts)
printf '  Second Bootstrap Code: %s\n' "$SECOND_BOOTSTRAP_CODE"
step "Enroll an independently usable second passkey with the new code."
step "Save the displayed Recovery Codes offline, then confirm their receipt in the PWA."
pause "Press Enter only after the PWA reports setup complete."
unset FIRST_BOOTSTRAP_CODE SECOND_BOOTSTRAP_CODE

stage "Register Bountywell read-only authority"
open_url "https://voice.stephens.page"
step "Sign in with a passkey."
step "Choose “Perform Fresh Passkey Action” and complete the passkey ceremony."
step "Choose “Register Bountywell read-only access”."
step "Confirm the PWA says five read-only capabilities are registered and no restart authority is present."
pause "Press Enter after the registration is visible."

stage "Register the owner telephone"
open_url "https://voice.stephens.page"
step "Choose “Perform Fresh Passkey Action” and complete the passkey ceremony."
step "In Registered Telephone, enter the owner telephone in E.164 form."
step "Enter $TELNYX_NUMBER as the dedicated Telnyx number."
step "Enter $LIVEKIT_INBOUND_TRUNK_ID and $LIVEKIT_OUTBOUND_TRUNK_ID as the fixed LiveKit route, then save the revision."
step "Confirm the PWA shows the intended owner number and a new Registered Telephone revision."
pause "Press Enter after the Registered Telephone is visible."

stage "Set the Silent Notification preference"
open_url "https://voice.stephens.page"
step "Choose “Perform Fresh Passkey Action” and complete the passkey ceremony."
ask OWNER_NOTIFICATION_EMAIL "Owner email for generic completion notices:"
step "In Silent Notifications, enter $OWNER_NOTIFICATION_EMAIL as the owner email."
step "Enter Voice Agent <tasks@$VOICE_AGENT_NOTIFICATION_SUBDOMAIN> as the sender identity."
step "Enter $VOICE_AGENT_NOTIFICATION_SUBDOMAIN as the verified notification subdomain, then save."
step "Confirm the PWA shows tracking disabled and the new preference revision."
pause "Press Enter after the Silent Notification preference is visible."
unset OWNER_NOTIFICATION_EMAIL

stage "Activate the Evidence lifecycle policy"
open_url "https://voice.stephens.page"
step "Choose “Perform Fresh Passkey Action” and complete the passkey ceremony."
step "Choose “Activate 90-day Evidence retention”."
step "Confirm the PWA reports the cutoff applied by the lifecycle policy."
pause "Press Enter after the Evidence lifecycle policy is active."

stage "Complete the real Callback Handshake smoke"
say "This bounded smoke waits up to three minutes for one new authorized Telephone Session."
step "When the command begins waiting, ring $TELNYX_NUMBER from the Registered Telephone."
step "Listen for the fixed callback notice, answer the outbound callback, and press 1 only after the prompt."
sudo -u voice-agent env \
  VOICE_AGENT_DATABASE_PATH=/var/lib/voice-agent/voice-agent.sqlite \
  /usr/bin/node --experimental-strip-types \
  /opt/voice-agent/current/apps/worker/src/callback-smoke.ts

stage "Answer Bountywell by telephone"
say "Keep the authorized callback connected. This smoke waits up to three minutes for a new finalized telephone health question and its complete Evidence Record."
step "When the command begins waiting, ask naturally whether Bountywell is healthy."
step "Listen for an answer that separates the primary health check from the expected authentication-boundary response."
sudo -u voice-agent env \
  VOICE_AGENT_DATABASE_PATH=/var/lib/voice-agent/voice-agent.sqlite \
  /usr/bin/node --experimental-strip-types \
  /opt/voice-agent/current/apps/worker/src/telephone-smoke.ts
open_url "https://voice.stephens.page"
step "Open the Callback Handshake Evidence Record and confirm it contains sanitized inbound, callback, machine-detection, DTMF, authorization, and outcome evidence."
step "Open the new Bountywell Evidence Record and confirm it contains the finalized turn, provider timing, Operation, bounded evidence, semantic response, and conclusion."
pause "Press Enter after the real spoken and visual evidence is verified."

stage "Run the bounded Bountywell production smoke"
say "This creates one real Durable Task and verifies public, local, systemd, and resource evidence."
sudo -u voice-agent -g voice-broker-client env \
  VOICE_AGENT_DATABASE_PATH=/var/lib/voice-agent/voice-agent.sqlite \
  VOICE_AGENT_BROKER_SOCKET_PATH=/run/voice-agent-broker/broker.sock \
  VOICE_AGENT_SMOKE_REQUEST_ID="production-smoke-$MERGED_COMMIT" \
  /usr/bin/node --experimental-strip-types \
  /opt/voice-agent/current/apps/worker/src/smoke.ts
sudo /usr/local/libexec/voice-agent/deployment-health.sh
say "A failed future promotion automatically restores the prior release."
say "Manual recovery: sudo /usr/local/libexec/voice-agent/rollback-release.sh <previous-commit>"
pause "Inspect the new Evidence Record in the PWA, then press Enter."

finish
